# Lições de aprofundamento (10–22): vida social, vizinhos, convites e amizades.

L(10, "Conhecer os vizinhos", "Even kennismaken met de buren.",
  ["Apresentar-se aos vizinhos e manter uma boa relação"],
  vocab=[V("v-buren","buren","vizinhos","noun","de"), V("v-buurtapp","buurtapp","grupo de mensagens do bairro","noun","de"),
         V("v-aanbellen","aanbellen","tocar à campainha","verb"), V("v-burenhulp","burenhulp","ajuda entre vizinhos","noun","de")],
  ex=[("We zijn net verhuisd en willen even kennismaken met de buren.","Acabámos de nos mudar e queremos conhecer os vizinhos."),("Ik heb bij de buren aangebeld.","Toquei à campainha dos vizinhos."),("In de buurtapp staan alle nieuwtjes.","No grupo do bairro estão todas as novidades."),("Burenhulp is hier heel normaal.","A ajuda entre vizinhos é muito normal aqui.")],
  review=["v-buurman","v-pakketje","v-aannemen","v-kennismaken"],
  cefr=C, exs=[
    MA([("buren","vizinhos"),("buurtapp","grupo do bairro"),("aanbellen","tocar à campainha"),("burenhulp","ajuda entre vizinhos")], "Vizinhos.", ["v-buren","v-buurtapp","v-aanbellen","v-burenhulp"]),
    DL([("Buurvrouw","Ja?","Sim?"),("Gonçalo","","")], ["*Hallo, ik ben Gonçalo, uw nieuwe buurman van nummer 12. Ik wilde even kennismaken.","Hallo, waar is de supermarkt?|Não se apresenta.","Ik bel aan.|Descreve o que já fez."], "Apresentar-se na porta.", ["v-aanbellen","v-kennismaken"]),
    CJ("aanbellen","ik","Ik heb twee keer ___, maar niemand deed open.", ["aangebeld"], "aan-ge-beld.", ["v-aanbellen"], tense="passado-perfeito"),
    TR("pt-nl","Podes receber a minha encomenda amanhã?", ["Kun je morgen mijn pakketje aannemen","Kunt u morgen mijn pakketje aannemen","Wil je morgen mijn pakketje aannemen"], "een pakketje aannemen.", ["v-pakketje","v-aannemen"]),
    TR("nl-pt","In de buurtapp staan alle nieuwtjes.", ["No grupo do bairro estão todas as novidades","No grupo de mensagens do bairro estão todas as novidades"], "staan = estar (escrito).", ["v-buurtapp"]),
    CO("text","Bericht in de buurtapp", "Hallo buren! Wij zijn Inês en Marco, de nieuwe bewoners van nummer 8. Zaterdag 15 juni vanaf 16.00 uur geven we een kleine borrel in onze tuin om kennis te maken. Iedereen is welkom, kinderen ook! Sorry voor het lawaai van de verbouwing de afgelopen weken. Groetjes!",
       [("Quem escreve?", ["*Os novos moradores do número 8","A câmara","O senhorio"]),("O que organizam?", ["*Um pequeno convívio no jardim","Uma reunião de condomínio","Uma venda de garagem"]),("Porque pedem desculpa?", ["*Pelo barulho das obras","Pelo lixo","Pelo carro"])],
       "Mensagem típica para conhecer a vizinhança.", ["v-buurtapp","v-buren"]),
    FB("Mijn ___ geven de planten water als ik op vakantie ben.", ["buren"], "Vizinhos.", ["v-buren"], choices=["buren","buurtapp","aanbellen"], tr="Os meus vizinhos regam as plantas quando estou de férias."),
    FE(["Ik","bel","morgen","bij","de","buren","aangebeld."], 6, "aan", "Presente: ik bel … aan.", ["v-aanbellen"]),
    LI("Als je iets nodig hebt, kun je altijd aanbellen.", ["Als je iets nodig hebt, kun je altijd aanbellen","Als je iets nodig hebt kun je altijd aanbellen"], "Se precisares de alguma coisa, podes sempre tocar à campainha.", "Oferta simpática.", ["v-aanbellen"]),
    WO("Queremos conhecer os vizinhos.", ["We","willen","kennismaken","met","de","buren"], "Modal + infinitivo.", ["v-buren"]),
  ], diff=3, mins=7)

L(11, "Um jantar em casa de amigos", "Wil je nog wat? Lekker toetje!",
  ["Comportar-se num jantar em casa de alguém: servir, elogiar, recusar"],
  vocab=[V("v-opscheppen","opscheppen","servir-se (de comida)","verb"), V("v-toetje","toetje","sobremesa","noun","het"),
         V("v-nog-wat","nog wat","mais um pouco","expression"), V("v-ik-zit-vol","ik zit vol","estou cheio (satisfeito)","expression")],
  ex=[("Schep maar lekker op!","Sirvam-se à vontade!"),("Wil je nog wat?","Queres mais um pouco?"),("Nee, dank je, ik zit echt vol.","Não, obrigado, estou mesmo cheio."),("Er is ook nog een toetje.","Também há sobremesa.")],
  review=["v-etentje","v-meenemen-iets","v-gastvrouw"],
  cefr=C, exs=[
    MA([("opscheppen","servir-se"),("toetje","sobremesa"),("nog wat","mais um pouco"),("ik zit vol","estou cheio")], "À mesa.", ["v-opscheppen","v-toetje","v-nog-wat","v-ik-zit-vol"]),
    AR("toetje","a sobremesa","het", "Diminutivo → het.", ["v-toetje"]),
    MC("Atenção: «opscheppen» também significa…", ["*gabar-se","lavar a loiça|Seria «afwassen».","pôr a mesa|Seria «de tafel dekken»."], "Hij schept altijd op over zijn auto = está sempre a gabar-se do carro.", ["v-opscheppen"]),
    DL([("Gastheer","Wil je nog wat aardappelen?","Queres mais umas batatas?"),("Rui","","")], ["*Nee, dank je, het was heerlijk, maar ik zit echt vol.","Nee, het is niet lekker.|Indelicado.","Ja, ik zit vol.|Contradição."], "Recusar educadamente.", ["v-ik-zit-vol"]),
    TR("pt-nl","Sirvam-se à vontade!", ["Schep maar lekker op","Schep maar op","Schept u maar op"], "maar suaviza o imperativo.", ["v-opscheppen"]),
    TR("nl-pt","Er is ook nog een toetje.", ["Também há sobremesa","Ainda há sobremesa"], "Er is = há.", ["v-toetje"]),
    CO("text","Etiquette bij een etentje", "Ben je uitgenodigd voor een etentje bij Nederlanders? Kom op tijd, niet een halfuur later. Neem een kleinigheid mee, zoals bloemen of een fles wijn. Aan tafel wacht je meestal tot iedereen heeft opgeschept en de gastvrouw of gastheer «eet smakelijk» zegt. Geef ook een compliment over het eten. En na het toetje? Vaak drink je nog koffie of thee voordat je naar huis gaat.",
       [("Quando se deve chegar?", ["*A horas","Meia hora depois","Uma hora antes"]),("Quando se começa a comer?", ["*Depois de todos se servirem e de se dizer «eet smakelijk»","Logo que se senta","Quando a comida arrefecer"]),("O que acontece depois da sobremesa?", ["*Muitas vezes bebe-se café ou chá","Vai-se logo embora","Lava-se a loiça"])],
       "Costumes à mesa.", ["v-opscheppen","v-toetje"]),
    FE(["Schep","maar","lekker","in!"], 3, "op", "Servir-se: opscheppen → Schep maar op!", ["v-opscheppen"]),
    LI("Het was echt heerlijk, mag ik het recept?", ["Het was echt heerlijk, mag ik het recept","Het was echt heerlijk mag ik het recept"], "Estava mesmo delicioso, posso ter a receita?", "Elogio clássico.", ["v-toetje"]),
    WO("Queres mais um pouco?", ["Wil","je","nog","wat?"], "Pergunta curta.", ["v-nog-wat"]),
  ], diff=3, mins=7)

