    LI("Via de vereniging heb ik veel nieuwe mensen leren kennen.", ["Via de vereniging heb ik veel nieuwe mensen leren kennen"], "Através da associação conheci muitas pessoas novas.", "leren kennen = conhecer.", ["v-lid"]),
    WO("Fiz-me sócio de um clube.", ["Ik","ben","lid","geworden","van","een","club"], "Perfectum com zijn.", ["v-lid-worden"]),
