       [("Onde é a cerimónia?", ["*Na câmara municipal de Haarlem","Numa igreja","Na praia"]),("O que se faz às 16h?", ["*A receção","O jantar","A cerimónia"]),("Que presente sugerem?", ["*Uma contribuição para a lua de mel","Loiça","Nada"])],
