    DL([("Joost","Kunnen jullie op 21 september?","Podem no dia 21 de setembro?"),("Ana","","")], ["*Ja, natuurlijk! We komen heel graag. Gefeliciteerd!","Nee, we trouwen niet.|Não responde.","Ja, wij zijn het bruidspaar.|Confuso."], "Aceitar com entusiasmo e felicitar.", ["v-trouwen"]),
    FE(["Ze","hebben","vorig","jaar","getrouwd."], 1, "zijn", "trouwen usa zijn: Ze zijn getrouwd.", ["v-trouwen"]),
