    MC("Ao convidar para jantar, é cortês perguntar…", ["*Heeft iemand dieetwensen of allergieën?","Hoeveel verdien je?|Indelicado.","Neem je eigen eten mee?|Não para um jantar."], "Pergunte sempre por alergias.", ["v-dieetwensen"]),
    TR("pt-nl","Sou alérgico a frutos secos.", ["Ik ben allergisch voor noten"], "allergisch voor.", ["v-allergisch"]),
    TR("pt-nl","A minha namorada é vegetariana.", ["Mijn vriendin eet vegetarisch","Mijn vriendin is vegetarisch","Mijn vriendin is vegetariër"], "vegetarisch eten.", ["v-vegetarisch"]),
    CO("dialogue","Een etentje plannen", "Inês: Zaterdag geef ik een etentje. Kunnen jullie om zeven uur?\nTom: Ja, leuk! Wat moet ik meenemen?\nInês: Niets, maar heeft iemand dieetwensen?\nTom: Lisa eet vegetarisch en ik ben allergisch voor schaaldieren.\nInês: Prima, dan maak ik een groentecurry. Als toetje maak ik pastéis de nata.",
       [("A que horas é o jantar?", ["*Às sete","Às oito","Às seis"]),("A que é alérgico o Tom?", ["*Marisco","Frutos secos","Leite"]),("O que vai cozinhar a Inês?", ["*Caril de legumes","Bacalhau","Bitoque"])],
       "Planear com restrições alimentares.", ["v-dieetwensen","v-vegetarisch","v-allergisch"]),
    FE(["Ik","ben","allergisch","tegen","pinda's."], 3, "voor", "allergisch voor.", ["v-allergisch"]),
    FB("Geef het even door als je ___ hebt.", ["dieetwensen"], "Restrições alimentares.", ["v-dieetwensen"], choices=["dieetwensen","vegetarisch","toetje"], tr="Avisa se tiveres restrições alimentares."),
    LI("Zijn er nog mensen die vegetarisch eten?", ["Zijn er nog mensen die vegetarisch eten","Zijn er nog mensen die vegetarisch eten?"], "Há mais alguém que seja vegetariano?", "die + verbo no fim.", ["v-vegetarisch"]),
    WO("Alguém tem restrições alimentares?", ["Heeft","iemand","dieetwensen?"], "Pergunta.", ["v-dieetwensen"]),
    SW("Escreva a mensagem de convite (4–5 frases) para um jantar em sua casa: dia, hora, menu, pergunta sobre alergias.", ["Hoi allemaal!\nZaterdag 12 oktober geef ik een Portugees etentje bij mij thuis. Jullie zijn welkom vanaf half zeven. Ik maak bacalhau à Brás en als toetje arroz doce. Laat even weten of jullie kunnen en of jullie dieetwensen of allergieën hebben!\nLiefs, Marta"], ["Dia e hora", "Menu", "Pergunta sobre restrições", "Pedido de resposta"], 40, "Convite para jantar.", ["v-dieetwensen","v-uitnodigen"]),
